#include <unistd.h>
#include <stdio.h>
int main() {
    int fd = open("my_file.txt", O_RDONLY);
    if (fd == -1) {
        perror("open"); // System call to handle and report errors
        return 1;
    }
    char buffer[1024];
    ssize_t bytes_read = read(fd, buffer, sizeof(buffer));
    if (bytes_read == -1) {
        perror("read"); // Another system call for error handling
        close(fd);
        return 1;
    }
    printf("%s\n", buffer);
    close(fd);
    return 0;
}
